#!/usr/bin/env python3
"""Build the block-1 inheritance narrative as an EPUB (for ElevenLabs listening).
Prose is TTS-oriented: English narrative, transliterated key terms glossed inline."""
import zipfile, html, time, os

OUT = "<repo-old>/logic/law_era/exo_21_block1_inheritance_narrative.epub"
TITLE = "The Ordinances Inherit — A Narrative of the Exodus 21 Experiment"

CHAPTERS = []  # (id, title, [paragraphs])

CHAPTERS.append(("ch01", "Chapter One. The Experiment", [
"""This is the story of an experiment. For months, a project called Torah Grok has been reading the Torah the way an engineer reads a codebase: not as a collection of stories and rules, but as one running program — one world, where every verse either declares something, changes something, or demands something that a later verse must supply. Each section of text is derived into a logic unit: a small machine with cases, handlers, statutes, and timers. When a unit passes its mechanical gates, it is frozen, and its facts enter the shared world. By the time this story begins, ninety-seven units were frozen, covering all of Genesis and the book of Exodus up through chapter twenty-one — the chapter where, for the first time, the Torah stops narrating and starts legislating.""",
"""Exodus twenty-one opens with the words: and these are the ordinances — in Hebrew, ve-eleh ha-mishpatim — which you shall set before them. What follows is the Torah's first sustained block of case law: the Hebrew slave who serves six years and goes free in the seventh; the ear pierced at the doorpost when he refuses his freedom; the daughter sold as a maidservant, an amah, whose sale is really a betrothal in disguise; the three duties a husband owes a wife — her food, her clothing, and her times — which may never be diminished. Eleven verses. On their face, they read in under a minute.""",
"""But the project had just learned a hard lesson. Its earlier derivations had leaned on one or two commentaries and called that the oral layer. The owner of the project issued a standing law: no verse may be derived again without the full use of the oral Torah — every single text in the tradition that comments on the passage must be read, completely, before a single line of logic is written. The tradition itself claims that the written verse is only a compressed surface, and that the real program lives in the oral explanation. If that claim is true, then deriving logic from the surface alone is decompiling a binary while ignoring the source code.""",
"""So the scan began. A census of the tradition's cross-reference graph found three thousand two hundred eighty-six listings anchored to these eleven verses. After ruling out the out-of-scope material, one thousand nine hundred sixty-two texts remained: readable commentaries, legal codes, midrash, responsa, kabbalistic treatises, grammar manuals, and twenty-six cross-references to other verses of the Bible. Over eighty-four sittings — bites, the project calls them — every one of those texts was read in full and logged in a ledger. Torah Temimah and both Mekhiltas. The Mishnah, the Tosefta, both Talmuds. Rambam's code, the Tur, the Shulchan Arukh. Rashi, Ibn Ezra, Ramban, Rashbam, Chizkuni, Sforno. The Vilna Gaon and the Malbim. Rav Hirsch and the Netziv. The Zohar's own treatise on this very portion. A thirteenth-century responsum about a divorce document delivered at night, and a fifteenth-century case about a housemaid who refused to run errands in the market. When the counter reached one thousand nine hundred sixty-two out of one thousand nine hundred sixty-two, a mechanical gate turned green: nothing readable remained unread.""",
"""Then came the derivation. The harvest was distilled into thirty-nine witnessed claims — every claim carrying its sources — and the claims were compiled into a machine: a running program, in Python, whose functions are the laws themselves. The court sale of a thief has a proportionality gate: he is sold whole or not at all, never by halves. The term has a clock, and the clock belongs to the sale, not to the calendar. The sick slave goes free on time; the runaway completes his flight-days. The declaration of the slave who loves his master must be said twice, inside a narrow window at the very end of his term, and only if a checklist of mutual love and health passes on both sides. The maidservant's redemption price falls by a flat share for every year she has served, at the original rate, though she is worth more now — the master subsidizes her exit by design. Every rule asserts itself against test vectors the tradition itself supplies; when the program runs, every assertion holds.""",
"""And then the owner asked the question this narrative exists to answer. Prove it, he said. Prove that this code depends on declarations from earlier verses — from Genesis, from Leviticus. Prove that the block inherits.""",
"""So the machine was given a table of its own imports: twenty-two declared dependency edges, each naming the element of the law that consumes something, the verse it consumes from, and the claim in the manifest that witnesses the wire. And a verifier was written that checks every edge against the project's own database of frozen units — the same index the web application runs on. If a source verse lies inside a frozen unit, the edge resolves, and the verifier names the unit. If it does not, the edge is a forward demand: a debt owed to a derivation that has not yet happened. The verifier enforces the declared direction of every edge with an assertion. Fifteen edges resolved backward into named, frozen units. Seven came up forward — genuine debts. And one edge, declared wrong, was caught by the machine itself and corrected. The chapters that follow walk each of those inheritances in detail: what the earlier code declared, what this block draws from it, and how the tradition wired the two together long before anyone thought to draw the graph.""",
]))

CHAPTERS.append(("ch02", "Chapter Two. The Shape of the Machine", [
"""Before the inheritances, hold the machine itself in your mind, because every inheritance lands on one of its parts.""",
"""Verse one is not a law. It is the runtime environment. And these are the ordinances which you shall set before them — the tradition reads every word of that header as configuration. Before them means before ordained judges in an unbroken chain of appointment reaching back to Moses: never before gentile courts, even when their law would produce the identical verdict, because the same output from a different engine is not the same law; and not before laymen either, though laymen can be cured by the consent of both parties, which a foreign court never can. You shall set carries the judges' instruments — the strap, the shofar for excommunication, the sandal for the release ceremony — which is to say, the power of coercion, vested only in the ordained. And set before them, like a laid table, is a command about teaching: the law must be served with its reasons showing, published so completely that the man it protects knows his own rights. One of the scan's crown findings, from the commentator Or HaChaim, says it flatly: a release-right that has not been published is void. The machine encodes all of this as its runtime dictionary, checked before any case runs.""",
"""Verse two opens the first case: when you acquire a Hebrew slave. The machine's entry function refuses more sales than it admits. It refuses women — a woman is never sold for her theft. It refuses solvent thieves, and confessions without witnesses. It refuses any sale where the theft is worth less than the man: sold whole, never half. It even lets the victim refuse, taking a promissory note instead. What survives all the gates is a six-year term on an anniversary clock, a dignity floor that bans the customs of slavery — no foot-washing, no litter-carrying, no trade-switching, equal bread and equal bedding, and, in the famous extreme, if there is one pillow in the house, the slave gets it.""",
"""Verses three and four handle his family. The master steps into the husband's place: he feeds the slave's wife, if she is truly his wife and with him, and his children until age six. If, and only if, the slave came in married, the master may give him a Canaanite bondwoman, a shifchah — and the machine encodes the reason the tradition gives: a single man would attach himself to her and refuse his freedom, so the permission is fenced to men whose first love waits outside. The children of that union follow their mother. That single clause — the woman and her children shall be her master's — is the Torah's matrilineal branch, and half of family-status law hangs from it.""",
"""Verses five and six are the refusal protocol. If the slave shall say, say — the doubled verb read as a doubled declaration — I love my master, my wife, my children, I will not go free: the machine demands the saying twice, while he is still a slave, inside the last perutah's worth of his service, with a bilateral checklist — he has a family and the master has a family, love on both sides, health on both sides. Only then the rite: presentation to the judges who sold him, the standing door, the right ear, the awl — and the tradition's own note that the halakhah overrides the awl to any instrument, one of the three canonical places where the received law uproots the written word. The pierced man serves to the yovel, the jubilee — his forever is bounded — and he serves no heir, because the love that held him was for one man only.""",
"""Verses seven through eleven are the second case: the daughter sold as an amah. Only a father can sell, only a minor daughter, only out of total destitution — the tradition requires him to have sold his house, his land, and his last shirt first — and only to a buyer who could lawfully marry her, because the sale is valid only if its marriage-exit works. Designation — yiud — turns the purchase money retroactively into betrothal money, and it requires her consent and his: the read text carries his refusal, the written text carries her veto. If neither he nor his son designates her, redemption is compulsory, priced by a falling flat rate. Nobody may ever resell her. And if the son takes her, she gets the full law of the daughters — which the tradition inverts into the source of every Jewish wife's rights: her food, her clothing, and her times, parameterized by season, by wealth, by occupation, with the third duty unwaivable by any contract. Her exits run as a minimum over events — six years, jubilee, puberty signs, the master's death, redemption — whichever comes first, frees her; except that designation is an absorbing state: once she is a wife, only a divorce document releases her.""",
"""That is the machine. Now the question: how much of it did this block actually invent — and how much did it inherit?""",
]))

CHAPTERS.append(("ch03", "Chapter Three. The Rhythm of Seven: Three Inheritances in One Constant", [
"""The first constant in the file is the term: six years of service, freedom in the seventh. Why six? The scan found the tradition answering with one voice: because that number was already declared, three times, in code this block can see.""",
"""The first declaration is the oldest one in the corpus. In the frozen unit that closes the creation week — the unit the verifier names, gen zero-six, land, Adam, and dominion — the world itself is built on a six-and-one frame: six days of work, and a seventh that is not work, blessed and set apart. When the slave-law machine imports its term, the verifier resolves the edge to Genesis one, verse thirty-one — the sixth day — inside that frozen unit. The commentator Rabbeinu Bachya, read in the scan, states the inheritance exactly: just as the Sabbath is a memorial of the works of creation, so is this law — the seventh year of the slave is his Sabbath. And Rav Hirsch, in the scan's most striking essay, turns the constant into the crime's own diagnosis: the thief sinned by grasping at the visible, material world — the six — and ignoring the invisible seventh that stands above ownership. So he repays in the same currency: six years inside the material, and the seventh sets him free. Six enslaves you, the essay concludes; seven makes you a free man.""",
"""The second declaration is the manna. In the frozen unit exo sixteen, manna and Sabbath, the six-and-one frame was scaled from days of creation to days of bread: gather six days; on the seventh, none falls. The frame proved portable — it survived translation from cosmology into economics. The slave law inherits that portability: if the week's shape can govern bread, it can govern years of labor.""",
"""The third declaration is Sinai itself. The frozen unit exo twenty, the ten utterances, installs the Sabbath command: six days shall you labor and do all your work. The verifier resolves the machine's third six-and-one edge to Exodus twenty, verse nine. And here the inheritance turns explicit in the sources: the version-one derivation of this very chapter had already noted that the slave's term is the six-and-one frame's third scale — days of creation, days of the manna week, years of a man's bondage. The scan deepened it: Abarbanel asks why six years and not ten or three, and answers that the constant is deliberately not derivable from reason — it is the signature of the creation week stamped into civil law, marking this code as revealed rather than rational. The Ramban says the seventh is chosen in days, in years, and in cycles of years, all one matter — the secret of the days of the world.""",
"""So when the machine's file says, in one line, term years equals six, that line is not an invention of block one. It is the third instantiation of a constant declared in Genesis, re-exported through the manna, and ratified at Sinai — and the dependency verifier proves all three wires land inside frozen, gate-passed units.""",
]))

CHAPTERS.append(("ch04", "Chapter Four. Marks of Egypt: the Four Hundred, the Doorposts, and the Ear", [
"""The piercing rite of verse six is the strangest procedure in the block: a man who refuses freedom is brought to the judges, stood against a door, and his ear is pierced with an awl. The scan found that every prop in that scene is an inheritance — the rite is built entirely out of earlier code.""",
"""Begin with the awl itself. In Hebrew it is called a martzea, and the medieval Tosafists — the Rosh, Hadar Zekenim, Paaneach Raza, all read in the scan — observe that its letters add to four hundred. Four hundred is not a random number in this corpus. In the frozen unit gen thirty-one, the covenant between the pieces, God tells Abram: your seed shall be strangers in a land not theirs, and they shall serve them, and they shall afflict them — four hundred years. That is the declaration. The inheritance runs like this: the four-hundred-year bondage was decreed, then mercifully shortened; the nation was carried out of it. A man who now stands at the door and says, I prefer bondage, is re-entering the very term his God closed early. So the instrument that marks him carries the number of the decree he is choosing back into. The verifier resolves the edge to Genesis fifteen, verse thirteen, inside the frozen covenant unit — the awl's number is a pointer into Abram's night vision.""",
"""Next, the door and the doorpost. Why is the ceremony staged there, of all places? The Talmud's answer, in tractate Kiddushin, was read in the scan in a dozen retellings: door and doorpost were My witnesses in Egypt. In the frozen unit exo twelve, Passover and the exodus, the blood of the Passover lamb is struck on the lintel and the two doorposts, and destruction passes over every marked house. At that hour, the tradition says, God declared: Mine are the children of Israel as slaves — My slaves, and not slaves of slaves. The doorposts heard that declaration; they are the standing witnesses of the night the nation's title changed hands. So when a man annuls that title — when he goes and acquires a master for himself — he is pierced before them: the witnesses of his emancipation watch him refuse it. Rav Hirsch adds the architectural grammar: the doorposts represent the independent house, which every freed slave was called to build; the door represents mere belonging to a house. The man who sells his independence for the comfort of belonging is pinned, by the ear, to the symbol of belonging, in the presence of the symbol of the home he declined. And the project's own records close the loop beautifully: the frozen Passover unit carries, in its oral audit, a claim about the precise spelling of the word doorposts — the very claim family this rite's stagecraft depends on. The verifier resolves the edge to Exodus twelve, verse seven, inside that audited unit.""",
"""Third, the ear. Why that organ? Rabban Yochanan ben Zakkai's homily, quoted across the whole shelf: the ear that heard at Sinai, do not steal, and went and stole — let it be pierced. The declaration lives in the frozen unit exo twenty, the ten utterances, at the eighth commandment. The scan preserved the tradition's own debugging of this inheritance, because there is a subtlety: the Decalogue's do not steal, in context, means kidnapping — a capital crime, not a sellable one. Three resolutions were logged. Chizkuni redirects the wire to the plural form of the theft-ban stated elsewhere. The Maharal and Mizrachi invoke the headline doctrine: each commandment was spoken with all its sub-clauses folded inside, so property-theft was heard at Sinai nested inside the kidnapping headline. And for the man who sold himself, the ear heard a different sentence: Mine are the children of Israel as slaves — and he contradicted it. Either way, the rite's target is selected by information history: the organ is punished for what it received and failed to keep. The verifier resolves the edge to Exodus twenty, verse thirteen.""",
"""One rite, three inherited props: a number from Abram's covenant, a stage from the Passover night, and an organ selected by what it heard at Sinai. None of it is decoration. Remove the earlier declarations, and the procedure of verse six becomes arbitrary; with them, every element is an execution of standing code.""",
]))

CHAPTERS.append(("ch05", "Chapter Five. The Family Files: Five Inheritances from Genesis", [
"""The deepest surprise of the scan was how much of this legal block the tradition reads as case law from the family stories of Genesis — as if the patriarchal narratives were the precedents, and Exodus twenty-one the codification. The verifier resolves five such edges, each into a named frozen unit.""",
"""The first is the Joseph sale. The commentator Kli Yakar asks why the entire civil code opens with the slave, and answers with a national memory: because the nation itself was once sold for a theft. In the frozen unit gen sixty, the dreamer sold, the brothers sell Joseph for silver — and the kabbalistic scan-sources trace the whole Egyptian bondage to that sale, exile as the long consequence of one trafficked brother. The code's first law is therefore an act of institutional memory: you, who were sold and went free, must build your own thief's servitude as a countdown with a guaranteed exit. The Megalleh Amukkot goes further: at Marah, where the first statutes were given, the accusing attribute objected that the Joseph sale still stood unatoned — and the ordinances, opening with when you acquire a Hebrew slave, are the sale's juridical echo. The verifier resolves the edge to Genesis thirty-seven, verse twenty-eight.""",
"""The second is Jacob's seven years. The halakhah forbids a man to sell himself except in destitution, and later authorities cap even voluntary labor contracts — the Chatam Sofer derived a three-year limit for hiring a rabbi from this very chapter. Then how did Jacob lawfully bind himself to Lavan for seven years — longer than the slave's own six — for Rachel's hand? The scan found the resolution in Pardes Yosef's appendix: for the sake of marriage, a mitzvah, the self-binding is permitted. The narrative case in the frozen unit gen fifty, the wage of seven years and the switched bride, is thereby closed against the statute: Jacob's contract is the carve-out that proves the rule. And Or HaChaim reads the pricing sentimentally: by exceeding the slave's six-year term, Jacob declared Rachel's worth above every bound servitude. The verifier resolves the edge to Genesis twenty-nine, verse eighteen.""",
"""The third is Hagar. The block's harshest clause — to a foreign people he shall not have power to sell her, seeing he has dealt deceitfully with her — is a one-way door: once a woman's status has been raised, it can never be traded back down. The midrash in Yalkut Shimoni puts this exact rule in Abraham's mouth. When Sarah demands that Hagar be dealt with, Abraham answers: after we have made her a mistress, we cannot make her a bondwoman again — and the midrash cites our verse. The frozen unit gen thirty-two, Hagar and the angel, carries the narrative; the statute in Exodus is its generalization. A status-elevation is irreversible; degradation is not a remedy. The verifier resolves the edge to Genesis sixteen, verse six.""",
"""The fourth is Rachel and Leah's grievance. The word the statute uses for the father's betrayal — be-vigdo bah, in his dealing deceitfully with her — is glossed by the Malbim and Sforno through a sentence spoken in Genesis: are we not counted by him as foreigners? for he has sold us. Rachel and Leah, in the frozen unit gen fifty-three, the flight over the river, indict their own father in the statute's exact terms: a father who sells his daughters has estranged them — made them foreigners in their own house. The daughters' complaint is the legal lexicon's source: selling a daughter is, definitionally, betrayal — which is why the law that permits it in extremis builds a marriage-track exit into the very sale. The verifier resolves the edge to Genesis thirty-one, verse fifteen.""",
"""The fifth is Jacob's vow. The three duties of verse ten — her food, her clothing, and her times — have a template older than the statute. At Bethel, in the frozen unit gen forty-eight, the ladder and the vow, Jacob asks for exactly three things: bread to eat, a garment to wear, and — the kabbalistic reading of the Megalleh Amukkot — that the Lord will be with me: presence. Food, clothing, presence. The scan logged the mapping explicitly: Jacob's vow is the maintenance triad in covenant form; what a man asks of God at the bottom of the ladder is what the law later obliges a husband to give a wife. The convert's grant in Deuteronomy — bread and garment, with no third term — is the contrast that proves the third term is the marital one. The verifier resolves the edge to Genesis twenty-eight, verse twenty.""",
"""Five family files, five wires. The pattern is worth stating: in this corpus, Genesis is not background. It is the precedent library — and the block's machine, checked mechanically, is running on it.""",
]))

CHAPTERS.append(("ch06", "Chapter Six. The Courtroom Inheritances: Marah, Jethro, and the Altar", [
"""The header verse — and these are the ordinances which you shall set before them — inherits its entire courtroom from three scenes already frozen in the corpus.""",
"""The first scene is Marah. Three chapters before Sinai, in the frozen unit exo fifteen, the song and Marah, the text says of the bitter-water station: there He set for him a statute and an ordinance. The Mekhilta reads the conjunction of our header — AND these are the ordinances — as pointing backward: as the former were from Sinai, so these; and the tradition's layered reading assigns Marah the general principles and our chapter the details. The scan even found the inheritance stamped into the letters: Kli Yakar and Paaneach Raza note that the final letters of the header's opening words spell Marah. The machine encodes this as its two-phase legislation note: the runtime knows its statutes were announced in general form before they were specified. The verifier resolves the edge to Exodus fifteen, verse twenty-five.""",
"""The second scene is Jethro's pyramid. Who is the them in set before them? The tradition answers: the judges Moses had just appointed on his father-in-law's advice — captains of thousands, hundreds, fifties, and tens, the frozen unit exo eighteen, Jethro and the judges. The Malbim, in one of the scan's structural finds, reads the sequence as constitutional design: Moses appointed no judges until the law was fixed and public, because judges ruling by private reasoning would never be accepted by the losing party — every loser would appeal back to Moses. First the published code, then the decentralized bench. And Shemot Rabbah preserves the staffing memo: Jethro's specification called for four qualities in a judge, and Moses, searching, found men with only one — so the written code itself, says the scan's boldest homily, compensates for the bench's missing virtues, section by section. The verifier resolves the edge to Exodus eighteen, verse twenty-one.""",
"""The third scene is the altar. The last verses before our chapter are altar law: you shall not ascend My altar by steps. From the adjacency, the Talmud derives that the great court sits beside the altar — and the tradition builds a full isomorphism on the seam: whatever disqualifies at the altar disqualifies on the bench. An unfit judge is an idolatrous tree planted beside the altar. The judge must walk his cases the way the priest walks the ramp — deliberately, without leaps. Solomon inscribed both triads, the judicial and the cultic, on the six steps of his throne. The scan's find from Pardes Yosef makes the connection administrative: the great court's daily work in its chamber beside the altar was vetting the priests who served at it. The machine's runtime carries this as its venue doctrine; the verifier resolves the edge to Exodus twenty, verse twenty-three, inside the frozen unit of the ten utterances.""",
"""Add these three to the header and the block's opening verse is revealed as almost entirely inherited: the law's provenance from Marah, its bench from Jethro, its venue from the altar, and its addressee — the ordained chain — from all three together.""",
]))

CHAPTERS.append(("ch07", "Chapter Seven. The Bondwoman Betrothed: the Error the Proof Caught", [
"""One inheritance deserves its own chapter, not because the wire is the deepest, but because of what happened when the machine checked it.""",
"""Leviticus nineteen, verse twenty, treats a strange case: a man lies with a woman who is a shifchah necherefet — a bondwoman designated to another man — and the text prescribes an indemnity, but no death penalty, because she was not free. Who is this half-bound woman? The halakhah answers: she is defined by our block. She is the Canaanite bondwoman assigned, under Exodus twenty-one verse four, to a Hebrew slave — the one union in the law where such an assignment is licensed. Half freed, betrothed to the one man permitted her, she is a status that exists only because our verse created the license. The dependency between the two passages is real and runs in both directions: Leviticus names a person our block invented; our block's assignment rule gains its gravity from the Leviticus case.""",
"""When the dependency table was first drafted, that edge was declared forward — a debt owed to an underived Leviticus. The verifier refused to run. Its assertion failed with a message naming the mistake: the source verse, Leviticus nineteen twenty, already lies inside a frozen unit — lev nineteen, the holiness duty ledger — derived in an earlier era of the project. The declaration was corrected to backward, the proof re-ran, and everything held.""",
"""It is worth pausing on why this small failure is the best news in the whole experiment. A proof that only ever confirms what its author believed is decoration. This one disagreed with its author, cited the database, and won. The corpus knew more than the person modeling it — which is exactly the property a one-world, code-is-physics simulation is supposed to have. The frozen units are not documentation; they are load-bearing state, and the verifier walks on them.""",
]))

CHAPTERS.append(("ch08", "Chapter Eight. The Seven Debts: What the Block Still Awaits", [
"""Fifteen edges resolve backward. Seven do not — and the honesty of those seven is the other half of the proof. The machine consumes constants from verses that no frozen unit yet supplies. In the project's language, these are open demands: the block is a standing creditor of derivations still to come.""",
"""Four of the seven debts point at a single chapter: Leviticus twenty-five. The largest is the yovel, the jubilee. Our block's machine contains the constant fifty, and the rule that the pierced slave's forever is bounded — le-olam means until the jubilee. But the jubilee itself — proclaim liberty throughout the land; each of you shall return to his holding and his family — is declared in Leviticus twenty-five, verse ten, which no unit has derived. Until it is, the slave law's outermost clock is imported from the future. The tradition is explicit about how hard this dependency binds: the codes rule that the entire Hebrew-slave module operates only when the jubilee operates — the block has an enable-flag wired to an institution it does not itself define. The scan even logged the Meshekh Chokhmah's contingency: if the jubilee lapses mid-term, the pierced slave's forever turns literal. A dormant dependency is still a dependency.""",
"""The second Leviticus debt is the other entry path. Our chapter's slave is the court-sold thief; the man who sells himself in destitution is legislated in Leviticus twenty-five, verse thirty-nine — a different class, with different rules the scan tabulated at length: no piercing, no bondwoman, a term set by contract, his children always leaving with him. The machine's class-split gate names that verse and waits for it.""",
"""The third is the block's deepest axiom. For Mine are the children of Israel as slaves — My slaves, whom I brought out of Egypt — Leviticus twenty-five, verse fifty-five. The scan found this sentence under everything: it is why the term is capped, why a worker may quit at midday, why the self-seller is rebuked, why the pierced ear is pierced, why — in Chizkuni's magnificent legal image — every human slave-sale is a junior lien: My document precedes any other document. The prior title of God in every Israelite body is the axiom the whole block enforces; and the verse that states it is not yet derived. The machine cites it as an imported axiom, marked open.""",
"""The fourth Leviticus debt is the children's bread. The master feeds the slave's children — but the verse that says so, he shall go out from you, he and his children with him, is Leviticus twenty-five, verse forty-one. The scan preserved the Chatam Sofer's beautiful computation of why our chapter names only the wife while Leviticus names the children: with a fixed six-year term, every child alive at the sale outgrows the six-year maintenance window before the exit; only the jubilee, which can cut a term short, leaves minor children to walk out — so each passage names exactly the dependents its own clock leaves possible. That is two constants from two books interlocking — and one of the books is still unwritten in the corpus.""",
"""The fifth debt is a single parameter: which ear? The right, says the halakhah — derived by verbal analogy from the leper's purification rite, where oil is placed on the right ear. That rite is Leviticus fourteen, verse fourteen — underived. The tradition itself flags this verse as a parameter server: one deliberately redundant word in the leper's law distributes the right-side setting to three separate procedures — the priest's handful, the release ceremony of the sandal, and our piercing. The machine imports the setting and marks the server verse open.""",
"""The sixth debt is a pair of categories. The priestly food law — Leviticus twenty-two, verse ten — says a priest's tenant and hired man may not eat the holy food, and the Talmud decodes the two words as our two slave-grades: the tenant is the pierced slave, acquired forever; the hired man is the six-year slave, acquired for years. Our block's two classes are load-bearing vocabulary in a law of another book — a dependency running outward as well as inward, and the outward anchor is underived.""",
"""The seventh debt is the parallel law itself. Deuteronomy fifteen restates the release — and adds the severance grant: when you send him out free, you shall not send him empty-handed. The scan's sources treat the restatement as a diff — the second passage supplies exactly the fields the first omitted — and the machine's severance table, who leaves with a grant and who does not, is imported wholesale from that chapter, verse twelve and onward. Underived; open.""",
"""Seven debts, honestly ledgered. When Leviticus twenty-five is finally scanned and derived — it is law-block seven on the owner's own list — four of these demands will close at once, and the verifier will flip them from open to resolved without a single edit to the block-one machine. That is what it means for the corpus to be one program: the imports are declared, and the linker is patient.""",
]))

CHAPTERS.append(("ch09", "Chapter Nine. One Program: What the Proof Means", [
"""Step back and look at what the experiment has actually shown.""",
"""Eleven verses of case law were read against one thousand nine hundred sixty-two texts of their own tradition — every readable word, a gate enforcing completeness. The harvest compiled into a machine whose assertions all hold, whose test vectors come from the tradition's own worked examples. And when the machine was asked to disclose its imports, it produced twenty-two edges, and a verifier proved fifteen of them resolve into earlier frozen code — the creation week, the covenant of the pieces, the Passover night, the Decalogue, Jethro's benches, Marah's statute, the altar's seam, and five family files from Genesis — while seven wait, ledgered, for Leviticus and Deuteronomy.""",
"""The claim this supports is the project's founding claim, and it is worth saying carefully. The Torah, read as this corpus reads it, behaves like a single program: constants declared early are consumed late; narratives function as precedents for statutes; a rite's props are pointers into prior scenes; and the dependencies are not homiletic decoration — they are checkable, because the earlier units were derived first and frozen with their facts. The six-year term is not explicable from inside Exodus twenty-one; it is the creation week's third instantiation. The piercing is not explicable at the door; it is the Passover night's witnesses recalled to testify. The maidservant's three duties are not invented in verse ten; they are Jacob's vow, codified. And the block's deepest axiom — My slaves, and not slaves of slaves — is imported from a chapter of Leviticus the project has not even reached, which the machine admits by carrying the debt on its books.""",
"""The tradition itself, the scan found, describes this architecture in its own words. Rav Hirsch: the written Torah is short notes on a lecture the nation lived for forty years; to the initiated, guiding stars; to the uninitiated, sphinxes. The Netziv: this portion is written with extreme compression, and parts of it cannot be understood at all without the received explanation. The Vilna Gaon, most radically: the halakhah uproots the plain verse in most of this portion, and that is the greatness of the oral law — the written text is the sealing-clay, and one must know the plain sense precisely in order to see what the seal impressed on it. The experiment's method — full inversion, then derivation, then a dependency proof — is nothing more than taking those three sentences literally and building the tooling they imply.""",
"""What remains is bookkeeping and horizon. The block-one machine is a draft: the frozen unit it will re-enter spans the whole chapter, and the coverage gate will not open until blocks two and three — the homicide and injury laws, and the goring ox — pass through the same full inversion. Beyond them stands Leviticus twenty-five, whose derivation will close four of the seven debts in a single stroke. The ledger is the cursor; the demands are filed; the linker is patient.""",
"""And one image from the scan is the right place to end. The midrash pictures the Torah given like a bride, escorted with laws before her and laws behind her — Marah's statute walking in front, these ordinances walking behind, the Presence in the middle. A corpus built that way is not a library of separate books. It is a procession — and every unit derived, from the creation week to the slave's seventh year, is another step of the same escort, holding hands with the steps before and after it. The proof, in the end, only made the hand-holding visible.""",
"""End of the narrative. This document describes an experimental computational model of the Torah's legal logic. It is a study artifact, not a work of binding religious law.""",
]))

# ---------------------------------------------------------------- build EPUB
def xhtml(cid, title, paras):
    body = "\n".join("<p>%s</p>" % p for p in paras)
    return """<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
<head><title>%s</title>
<style>body{font-family:Georgia,serif;line-height:1.6;margin:5%%;}
h2{font-size:1.2em;} p{text-align:justify;margin:0 0 1em 0;}</style></head>
<body><h2>%s</h2>
%s
</body></html>""" % (html.escape(title), html.escape(title), body)

os.makedirs(os.path.dirname(OUT), exist_ok=True)
with zipfile.ZipFile(OUT, "w") as z:
    z.writestr("mimetype", "application/epub+zip", zipfile.ZIP_STORED)
    z.writestr("META-INF/container.xml", """<?xml version="1.0" encoding="utf-8"?>
<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">
<rootfiles><rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/></rootfiles>
</container>""")
    manifest, spine, navlis = [], [], []
    for cid, title, paras in CHAPTERS:
        fn = "%s.xhtml" % cid
        z.writestr("OEBPS/" + fn, xhtml(cid, title, paras))
        manifest.append('<item id="%s" href="%s" media-type="application/xhtml+xml"/>' % (cid, fn))
        spine.append('<itemref idref="%s"/>' % cid)
        navlis.append('<li><a href="%s">%s</a></li>' % (fn, html.escape(title)))
    nav = """<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
<head><title>Contents</title></head>
<body><nav epub:type="toc" id="toc"><h1>Contents</h1><ol>
%s
</ol></nav></body></html>""" % "\n".join(navlis)
    z.writestr("OEBPS/nav.xhtml", nav)
    opf = """<?xml version="1.0" encoding="utf-8"?>
<package xmlns="http://www.idpf.org/2007/opf" version="3.0" unique-identifier="uid">
<metadata xmlns:dc="http://purl.org/dc/elements/1.1/">
<dc:identifier id="uid">urn:torah-grok:law01:inheritance-narrative:2026-08-11</dc:identifier>
<dc:title>%s</dc:title>
<dc:language>en</dc:language>
<dc:creator>Torah Grok — the law era, block one</dc:creator>
<meta property="dcterms:modified">%s</meta>
</metadata>
<manifest>
<item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/>
%s
</manifest>
<spine>
%s
</spine>
</package>""" % (html.escape(TITLE), time.strftime("%Y-%m-%dT%H:%M:%SZ"),
                 "\n".join(manifest), "\n".join(spine))
    z.writestr("OEBPS/content.opf", opf)

words = sum(len(p.split()) for _, _, ps in CHAPTERS for p in ps)
print("EPUB written: %s (%d KB, %d chapters, ~%d words, ~%d min listening)"
      % (OUT, os.path.getsize(OUT)//1024, len(CHAPTERS), words, words//150))
